func (s *Server) placeOrder(w http.ResponseWriter, r *http.Request) {
    tx, err := s.db.BeginTx(r.Context(), nil)
    if err != nil { http.Error(w, err.Error(), http.StatusInternalServerError); return }
    defer tx.Rollback()                       // no-op after a successful commit

    if err := s.reserveStock(r.Context(), tx, req); err != nil { http.Error(w, err.Error(), http.StatusConflict); return }
    if err := s.insertOrder(r.Context(), tx, req); err != nil { http.Error(w, err.Error(), http.StatusInternalServerError); return }
    if err := tx.Commit(); err != nil { http.Error(w, err.Error(), http.StatusInternalServerError); return }
    w.WriteHeader(http.StatusCreated)
}
